    "urduText": "(2) نبوت و رسالت\nاس سبق کی تکمیل پر آپ اس قابل ہو جائیں گے کہ :\nاس بات کو سمجھ کر ایمان پختہ کریں کہ تمام انبیاء کرام علیھم السلام کو اللہ تعالیٰ نے انسانوں کی رہنمائی کے لیے مبعوث فرمایا۔ اس بات پر ایمان پختہ کریں کہ نبی کریم صلی اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ اللہ تعالیٰ کے آخری نبی اور رسول ہیں\nاور آپ صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَ أَصْحَابِهِ وَسَلَّمَ کے بعد ہمیشہ کے لیے کوئی نبی یا رسول نہیں آئے گا۔\nانبیاء کرالعلیهم السلام اللہ تعالی کے بھیجے ہوئے خاص بندے ہیں۔\nانبیاء کرامعلیم السلام نے ایک اللہ تعالیٰ کی عبادت کرنے کا حکم دیا۔\nانبیاء کر اعلیکم السلام نے لوگوں کو اچھے کام کرنے کا حکم دیا۔\n14\nNOT-FOR-SALE\nدل چسپ بات\nحضرت جبریل علیہ السلام اللہ تعالیٰ کا پیغام تمام انبیاء کرام علیہم السلام تک پہنچایا کرتے تھے۔\nہم تمام انبیاء کرام علیھم السلام پر ایمان لاتے ہیں ۔\nاللہ تعالیٰ کے پہلے نبی حضرت آدم علیہ السلام ہیں اور آخری نبی حضرت محمد رسول الله خاتم النبينَ صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَأَصْحَابِهِ وَسَلَّمَ ہیں ۔\nہمارے پیارے نبی کا نام حضرت محمد رسول الله عالم الن صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ ہے۔\nآپ صَلَّى اللهُ عَلَيْهِ وَعَلَى الِیهِ وَ أَصعلیہ و سلم کے بعد قیامت تک کوئی نبی یا رسول نہیں آئے گا۔\nآئیں جائیں\nمشہور انبیاء کرام علیہم السّلام کے نام :\nحضرت نوح علیہ السّلام حضرت ابراہیم علیہ السّلام حضرت موسیٰ علیہ السّلام حضرت عیسی علیہ السّلام آخری نبی حضرت محمد رسول اللہ غالَ الَّذِيْنَ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ\n15\n1 خالی جگہ پر کریں۔\nمشق\nخاص\nحضرت آدم علیہ السلام\nایمان\nا۔\nاللہ تعالی کے پہلے نبی کا نام ۔\nب۔ ہم انبیاء کرام علیهم السلام ہے ۔\nج انبیاء کرام علیھم السلام اللہ تعالیٰ کے بھیجے ہوئے\n2 اللہ تعالیٰ کے آخری نبی کا نام بتا ئیں۔\nہے۔",
