    "urduText": "کے اخلاق حسنہ\nاس سبق کی تکمیل پر آپ اس قابل ہو جائیں گے کہ :\nحضرت محمد رسول الله عام النبي صلى اللَّهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّم کے صادق اور امین ہونے کو جان سکیں۔ سیرت طیبہ کی روشنی میں اخلاق حسنہ کے پہلوؤں کو اپنا سکیں۔\nایک مرتبہ ہمارے نبی حضرت محمد رسول الله قائم البينَ صَلَّى اللهُ عَلَيْهِ وَعَلَى اللِهِ وَأَصْحَابِهِ وَسَلَّمَ صفا پہاڑی پر چڑھے اور مکہ\nوالوں کو آواز دی ۔ سب لوگ جلدی جلدی آپ صلى الله عَلَيْهِ و عَلى البيه واضعلیہ وسلم کے پاس جمع ہو گئے۔\nآپ صلى الله عَلَيْهِ وَعَلَى البو صعلیہ وسلم نے لوگوں سے پوچھا: تم لوگوں نے مجھے کیسا پایا ہے؟\nسب بولے : آپ صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ صادِق اور امین ہیں ۔\nتب آپ صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِہ وَسَلَّمَ نے فرمایا : تم سب کہہ دو کہ اللہ تعالیٰ کے علاوہ کوئی عبادت کے\nلائق نہیں تو تم فلاح پا جاؤ گے۔ (مسند احمد ، حدیث 10598)\nآپ صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَأَصْحَابِهِ وَسَلَّمَ ہمیشہ سچ بولتے تھے ۔ آپ صلی اللہ عليْهِ وَعَلَى آلِهِ وَأَصْحَابِهِ وَسَلَّمَ نے ہمیشہ\nامانتوں کا خیال رکھا۔ کا فر بھی اپنی چیزیں آپ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ کے پاس رکھوایا کرتے تھے۔\nآپ صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِہ وَسَلَّمَ نے دوسروں کو بھی\nسچائی اور امانت داری سکھائی۔\nآئیں جائیں\nصادق کا مطلب ہے ہمیشہ سچ بولنے والا امین کا مطلب ہے دوسروں کی چیزوں کا\nخیال رکھنے والا\n35\nآئیں جائیں\nسچ بولنے والے کو اللہ تعالیٰ پسند کرتا ہے۔\nآپ صلی الله عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ نے فرمایا :\nسچ نیکی کی طرف لے جاتا ہے۔ (صحیح بخاری ، حدیث : 6094)\nجس میں امانت نہیں وہ مومن نہیں۔ (صحیح ابن حبان ، حدیث : 194)\nہمیں چاہیے کہ ہم بھی اپنے پیارے نبی حضرت محمد رسول الله قائم التين صلى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ کی طرح ہمیشہ\nسچ بولیں اور دوسروں کی امانت کا خیال رکھیں۔\n36\nNOT-FOR-SALE\nمشق\n1 خالی جگہ پر کریں۔\nنیکی\nچیزیں",
