    "urduText": "باب چهارم اخلاق و آداب (1) اچھے اخلاق\nحاصلات تعلم :\nاس سبق کی تکمیل پر آپ اس قابل ہو جائیں گے کہ :\nقرآن وسنت کی روشنی میں اچھے اخلاق سے متعلق جان سکیں۔\nاپنی عملی زندگی میں اچھے اخلاق کو اپنا سکیں۔\nایک مرتبہ ہمارے نبی حضرت محمد رسول الله نائم المنين صلى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَبهِ وَسَلَّمَ اپنے ساتھیوں کے ساتھ سفر کر رہے تھے۔ ایک جگہ پہنچ کر سب لوگ کچھ وقت کے لیے رکے تھوڑی دیر بعد آپ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ نے دیکھا کہ ایک چڑیا مسلسل چوں چوں کر رہی ہے ۔ آپ صلى اله علیه وسل الیہ و آلہ وسلم نے اپنے ساتھیوں سے پوچھا کہ اس چڑیا کو کیا ہوا ہے۔ ساتھیوں نے بتایا کہ فلاں شخص نے اس چڑیا کے گھونسلے سے اس کے بچے اٹھا لیے ہیں۔ آپ صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَلہ و سلم نے اس شخص کو بلا یا اور حکم دیا کہ فوری بچے چڑیا کے گھونسلے میں رکھ دے۔ جب اس نے بچے گھونسلے میں رکھے تو چڑیا خوش ہو کر خاموش ہوگئی ۔ (سنن ابو داؤد، حدیث :3089)\nآپ صلى الله عَلَيْهِ مَل الهوَ أَصْعَليه وسلم انسانوں کے ساتھ ساتھ جانوروں سے بھی اچھا سلوک کیا کرتے تھے۔\nکیا آپ جانتے ہیں؟\nفرمان الہی ....\nبہت سارے کا فر ہمارے نبی حضرت محمد رسول الله عالم المین صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ یقینا آپ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ\nکے اچھے اخلاق کی وجہ سے مسلمان ہو گئے تھے۔\nاخلاق کے اعلی مر تبہ پر فائز ہیں۔\n39\nاللہ تعالیٰ نے ہمارے نبی حضرت محمد رسول الله عالم النينَ صَلَّى اللهُ عَلَيْهِ وَعَلَى اللهِ وَأَصْحَابِہ وَسَلَّمَ کو اس لیے بھیجا کہ\nوہ ہمیں اچھی اچھی باتیں سکھائیں۔ آپ صلی اللہ علیہ و علی الہ و علیہ وسلم نے ہمیں سکھایا کہ ہم :\n*\nاپنے امی ابو کی بات مانیں۔\nبہن بھائیوں اور دوستوں کے ساتھ مل جل کر رہیں۔\nدوستوں کو اچھے نام سے پکاریں۔\nوقت کی پابندی کریں۔\nاپنی باری کا انتظار کریں۔\nبڑوں کا ادب کریں۔\nدوسروں کو سلام کرنے میں پہل کریں۔\nفرمان مصطفى صَلَّى اللهُ عَلَيْهِ وَعَلَى الِهِ وَأَصْحَابِهِ وَسَلَّمَ\nتم میں سے اچھا وہ ہے جس کے اخلاق اچھے ہیں۔ (سنن ترمذی ، حدیث : 1162)\n40\nNOT-FOR-SALE\n1 خالی جگہ پر کریں۔\nاجازت\nمشق",
